/**
 * modules/CoreModule/liuyao-wangshuai.js —— 六爻旺衰进阶 C28【单一真源 · 适配层】
 *
 * 算什么：在 liuyao.js（装卦/纳甲/世应/六亲/六神/飞伏）之上，补「旺衰进阶」这一层——
 *         ① 五行生旺墓绝（长生/帝旺/墓/绝）② 月建日辰旺衰档 ③ 日冲→暗动·日破
 *         ④ 动爻化变（回头生克 / 化进神退神 / 化墓化绝 / 化空化破 / 伏吟反吟）
 *         ⑤ 三合局成局与虚一待用 ⑥ 六冲卦·六合卦·游魂归魂 ⑦ 用神·原神·忌神·仇神定位
 *
 * 算法来源（有权威用权威，零臆造；多源逐字核对一致）：
 *   · 生旺墓绝（《卜筮正宗·生旺墓绝章》原文，5 源逐字一致）：
 *       金长生在巳、旺在酉、墓在丑、绝在寅；
 *       木长生在亥、旺在卯、墓在未、绝在申；
 *       火长生在寅、旺在午、墓在戌、绝在亥；
 *       水、土长生在申、旺在子、墓在辰、绝在巳。
 *     ⚠ 觉子原注三条例外（本内核已内建）：
 *       ① 金虽长生在巳，须金爻旺相方论生；休囚遇巳午火多则论克不论生（烈火煎金）。
 *       ② 金虽墓于丑，得未土冲动或卦中土多生金，则论生不论墓。
 *       ③ 土爻绝于巳，须休囚无气方论绝；旺相得生扶则巳火反生土，论生不论绝。
 *     📌 流派差异：土之长生另有「寅」说（戊土生寅/己土生酉，《易冒》并存），
 *       《卜筮正宗》以天时考证定「土寄生于申」，本内核取申，如实标注不合并。
 *   · 月建日辰（《增删卜易·月建章/日辰章》）：月建司一月之权为提纲，日辰司一日之权为主宰；
 *       两者皆能生、克、冲、合卦爻。月建冲爻为「月破」；日辰冲爻，旺相为「暗动」、休囚为「日破」
 *       （《增删卜易·六冲章》原文：「爻遇日冲为暗动，休囚而遇日冲谓之日破。」）。
 *     📌 流派差异：月建冲「临日辰」之静爻，一派作暗动（本内核择此，并标注），一派认为月冲无暗动。
 *   · 旺衰判定档（《增删卜易》日月权衡表，4 源一致）：
 *       临月建+临日辰=旺上加旺；临月建+日生=旺（有根）；月扶+临日辰=得时得地；
 *       月克+日生=休囚有气（有救）；月克+日克=休囚无救；月破+日克=衰败已极。
 *   · 进神退神（《卜筮正宗·进退神论》原文 7 组，5 源一致）：
 *       进神：亥化子、寅化卯、巳化午、申化酉、丑化辰、辰化未、未化戌。
 *       退神：子化亥、卯化寅、午化巳、酉化申、辰化丑、未化辰、戌化未。
 *       口诀：「进者吉凶倍增其势，退者吉凶渐减其威。」进神为放大器，退神为衰减器。
 *     📌 流派差异：部分书补「戌化丑」为进神（土气一周复始），《卜筮正宗》原文未列 → 本内核单列提示，不并入主判。
 *   · 三合局（《卜筮正宗·三合章》原文，5 源一致）：
 *       申子辰合水局、寅午戌合火局、亥卯未合木局、巳酉丑合金局。
 *       成局四法：① 三爻齐动 ② 两爻动＋一爻不动（静爻亦得借势） ③ 内卦初/三爻动、外卦四/六爻动，连变爻成局
 *       ④ 两爻动而日建/月建凑第三支（含「中神动、日月凑另两支」）。
 *       只有两爻动、日月又无第三支 → 不成局，为「虚一待用」（断应期）。
 *       局中一爻旬空或月破 → 待填实/解破之日成局。
 *   · 反吟伏吟（《卜筮正宗·反吟伏吟论》原文，4 源一致）：
 *       卦之反吟（卦变相冲）：乾↔巽、坎↔离、震↔兑、坤↔艮（坤艮因丑未、寅申相冲）。
 *       爻之反吟：动爻与变爻地支六冲（子化午、丑化未…）。
 *       卦之伏吟：变卦六爻地支与本卦全同（内外伏吟=乾↔震；外卦伏吟=恒↔姤等；内卦伏吟=屯↔需等）。
 *       爻之伏吟：动爻化出同支（寅化寅、辰化辰…）。
 *       断：「反吟主反复不安、成而复败；伏吟主呻吟迟滞、事多不遂。」
 *   · 六冲卦十、六合卦八（占筮通用定论，4 源逐字一致）：
 *       六冲：乾为天、兑为泽、离为火、震为雷、巽为风、坎为水、艮为山、坤为地（八纯皆六冲）＋雷天大壮、天雷无妄。
 *       六合：天地否、地天泰、雷地豫、地雷复、火山旅、水泽节、山火贲、泽水困。
 *   · 六亲生克链（京房纳甲通用）：原神=生用神者、忌神=克用神者、仇神=克原神者（＝生忌神）。
 *
 * 加载：UMD —— require（注入 liuyao）；浏览器挂 NT.core.liuyaoWangshuai。
 * 校验：modules/CoreModule/__tests__/liuyaowangshuai.test.js
 *
 * 交叉验证状态（守零臆造，如实标注）：
 *   ✅ 生旺墓绝表、进退神 7 组、三合四局、六冲/六合卦定数、月建日辰权柄 —— 经典定论，多源一致，无歧义。
 *   📌 已标注的流派分歧（不合并、不假报）：土长生申/寅；月冲临日之爻是否作暗动；戌化丑是否进神。
 *   📌 「旺衰档」为《增删卜易》日月权衡表的直接落地，不是自造打分；档位只做定性（旺/相/平/衰），不出分数。
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) {
    module.exports = factory(require('./liuyao.js'));
  } else {
    root.NT = root.NT || {}; root.NT.core = root.NT.core || {};
    root.NT.core.liuyaoWangshuai = factory(root.NT.core && root.NT.core.liuyao);
  }
})(typeof self !== 'undefined' ? self : this, function (LYAO) {

  // ===== 基础表 =====
  var ZHI = '子丑寅卯辰巳午未申酉戌亥';
  function zIdx(z) { return ZHI.indexOf(z); }
  var Z_WX = { 子: '水', 丑: '土', 寅: '木', 卯: '木', 辰: '土', 巳: '火', 午: '火', 未: '土', 申: '金', 酉: '金', 戌: '土', 亥: '水' };

  var SHENG = { 木: '火', 火: '土', 土: '金', 金: '水', 水: '木' };  // 我生
  var KE = { 木: '土', 土: '水', 水: '火', 火: '金', 金: '木' };     // 我克
  function 生我(w) { for (var k in SHENG) if (SHENG[k] === w) return k; return null; }
  function 克我(w) { for (var k in KE) if (KE[k] === w) return k; return null; }

  // 生旺墓绝（《卜筮正宗·生旺墓绝章》原文）
  var SHENG12 = {
    木: { 长生: '亥', 帝旺: '卯', 墓: '未', 绝: '申' },
    火: { 长生: '寅', 帝旺: '午', 墓: '戌', 绝: '亥' },
    金: { 长生: '巳', 帝旺: '酉', 墓: '丑', 绝: '寅' },
    水: { 长生: '申', 帝旺: '子', 墓: '辰', 绝: '巳' },
    土: { 长生: '申', 帝旺: '子', 墓: '辰', 绝: '巳' }
  };

  // 进神 / 退神（《卜筮正宗·进退神论》原文 7 组）
  var JIN = { 亥: '子', 寅: '卯', 巳: '午', 申: '酉', 丑: '辰', 辰: '未', 未: '戌' };
  var TUI = { 子: '亥', 卯: '寅', 午: '巳', 酉: '申', 辰: '丑', 未: '辰', 戌: '未' };

  // 六合（地支）
  var HE = { 子: '丑', 丑: '子', 寅: '亥', 亥: '寅', 卯: '戌', 戌: '卯', 辰: '酉', 酉: '辰', 巳: '申', 申: '巳', 午: '未', 未: '午' };
  function 支合(a, b) { return HE[a] === b; }
  function 支冲(a, b) { return !!(a && b) && ZHI[(zIdx(a) + 6) % 12] === b; }

  // 三刑（占筮与命理同源）
  var XING_GROUP = [['寅', '巳', '申'], ['丑', '戌', '未']];
  var ZI_XING = ['辰', '午', '酉', '亥'];
  function 支刑(a, b) {
    if (a === b) return ZI_XING.indexOf(a) >= 0;
    if ((a === '子' && b === '卯') || (a === '卯' && b === '子')) return true;
    for (var i = 0; i < XING_GROUP.length; i++) {
      if (XING_GROUP[i].indexOf(a) >= 0 && XING_GROUP[i].indexOf(b) >= 0) return true;
    }
    return false;
  }

  // 三合局（中神五行即局五行）
  var SAN_HE = [
    { 支: ['申', '子', '辰'], 局: '水', 中神: '子' },
    { 支: ['亥', '卯', '未'], 局: '木', 中神: '卯' },
    { 支: ['寅', '午', '戌'], 局: '火', 中神: '午' },
    { 支: ['巳', '酉', '丑'], 局: '金', 中神: '酉' }
  ];

  // 六冲卦十 / 六合卦八
  var CHONG_GUA = ['乾为天', '兑为泽', '离为火', '震为雷', '巽为风', '坎为水', '艮为山', '坤为地', '雷天大壮', '天雷无妄'];
  var HE_GUA = ['天地否', '地天泰', '雷地豫', '地雷复', '火山旅', '水泽节', '山火贲', '泽水困'];

  // 卦之反吟（八纯相冲对）
  var FAN_YIN_PAIR = [['乾', '巽'], ['坎', '离'], ['震', '兑'], ['坤', '艮']];

  // ===== ① 月建关系 =====
  function 月关系(爻支, 爻五行, 月支) {
    if (!月支) return { 类: '未定', 分: 0, 说明: '未给月建，旺衰未定。' };
    var 月Wx = Z_WX[月支];
    if (爻支 === 月支) return { 类: '临月建', 分: 2, 说明: '爻支与月建同支，得月建之权，一月内最旺。' };
    if (支冲(爻支, 月支)) return { 类: '月破', 分: -2, 说明: '月建冲爻为月破；出月、逢合、值日可解。' };
    if (SHENG[月Wx] === 爻五行) return { 类: '月生', 分: 1.2, 说明: '月建五行生爻，得生为旺相。' };
    if (月Wx === 爻五行) return { 类: '月扶', 分: 1.2, 说明: '月建与爻同五行，得扶为旺相。' };
    if (SHENG[爻五行] === 月Wx) return { 类: '月泄', 分: -0.6, 说明: '爻生月建，泄气，力减。' };
    if (KE[爻五行] === 月Wx) return { 类: '月耗', 分: -0.6, 说明: '爻克月建，耗力，力减。' };
    if (KE[月Wx] === 爻五行) return { 类: '月克', 分: -1.2, 说明: '月建克爻，休囚无根。' };
    return { 类: '未定', 分: 0, 说明: '' };
  }

  // ===== ② 日辰关系 =====
  function 日关系(爻支, 爻五行, 日支) {
    if (!日支) return { 类: '未定', 分: 0, 说明: '未给日辰，旺衰未定。' };
    var 日Wx = Z_WX[日支];
    if (爻支 === 日支) return { 类: '临日辰', 分: 2, 说明: '爻支与日辰同支，得日辰之权，当日最旺。' };
    if (支冲(爻支, 日支)) return { 类: '日冲', 分: 0, 说明: '日辰冲爻：旺相为暗动，休囚为日破（见下判定）。' };
    if (SHENG[日Wx] === 爻五行) return { 类: '日生', 分: 1.2, 说明: '日辰生爻，有气得力。' };
    if (日Wx === 爻五行) return { 类: '日扶', 分: 1.2, 说明: '日辰与爻同五行，得扶得力。' };
    if (SHENG[爻五行] === 日Wx) return { 类: '日泄', 分: -0.6, 说明: '爻生日辰，泄气。' };
    if (KE[爻五行] === 日Wx) return { 类: '日耗', 分: -0.6, 说明: '爻克日辰，耗力。' };
    if (KE[日Wx] === 爻五行) return { 类: '日克', 分: -1.2, 说明: '日辰克爻，受损。' };
    return { 类: '未定', 分: 0, 说明: '' };
  }

  // ===== ③ 旺衰档（《增删卜易》日月权衡表直接落地，只出定性档位）=====
  function 旺衰档(月类, 日类) {
    if (月类 === '月破' && (日类 === '日克' || 日类 === '日耗' || 日类 === '日泄')) return '衰败已极';
    if (月类 === '月破' && 日类 === '临日辰') return '月破反作暗动（值日不破）';
    if (月类 === '月破') return '月破失力';
    if (月类 === '月克' && 日类 === '日克') return '休囚无救';
    if (月类 === '月克' && (日类 === '日生' || 日类 === '日扶' || 日类 === '临日辰')) return '休囚有气（有救）';
    if (月类 === '临月建' && 日类 === '临日辰') return '旺上加旺';
    if (月类 === '临月建' && (日类 === '日生' || 日类 === '日扶')) return '旺（有根有力）';
    if ((月类 === '月生' || 月类 === '月扶') && 日类 === '临日辰') return '得时得地';
    if (月类 === '临月建') return '旺（有根）';
    if (月类 === '月生' || 月类 === '月扶') return '相（有气）';
    if (日类 === '临日辰' || 日类 === '日生' || 日类 === '日扶') return '平（得日辰之助）';
    if (月类 === '未定' && 日类 === '未定') return '未定';
    return '休囚（无根无助）';
  }

  // 档位 → 强弱分档（用于「原神/忌神是否有生克权」的定性，不出分数）
  function 档强弱(档) {
    if (/旺上加旺|有根有力|得时得地/.test(档)) return '旺';
    if (/旺（有根）|相（有气）/.test(档)) return '相';
    if (/平（/.test(档)) return '平';
    if (/休囚有气/.test(档)) return '弱有救';
    if (/休囚无救|无根无助|月破失力|衰败已极/.test(档)) return '衰';
    if (/冲散|日破/.test(档)) return '衰';
    if (/暗动/.test(档)) return '暗动（力增）';
    return '未定';
  }

  // ===== ④ 动爻化变（回头生克 / 进退 / 化墓化绝 / 化空化破 / 伏吟反吟）=====
  function 变爻关系(本支, 变支, 月支, 日支, 空亡) {
    if (!变支) return null;
    var 本Wx = Z_WX[本支], 变Wx = Z_WX[变支];
    var S = SHENG12[本Wx] || null;
    var tags = [];

    // 4.1 爻之伏吟 / 爻之反吟（地支层面，最优先取象）
    if (变支 === 本支) {
      tags.push({ 名: '伏吟', 级: '凶', 断: '动爻化出同支，为爻之伏吟：主呻吟迟滞、事多反复、进退两难。' });
    } else if (支冲(本支, 变支)) {
      tags.push({ 名: '反吟', 级: '凶', 断: '动爻化出冲支，为爻之反吟：主反复不安、成而复败、去而复返。' });
    }

    // 4.2 化墓 / 化绝 / 化长生 / 化帝旺（象层；墓绝须兼看旺衰，见注）
    if (S) {
      if (变支 === S.墓) tags.push({ 名: '化墓', 级: '凶', 断: '动爻化入本五行之墓（' + 本Wx + '墓在' + S.墓 + '）：主困住难出、事入坟墓之象。', 注: '觉子原注：爻旺相得生扶或墓支被冲，则论生不论墓。' });
      else if (变支 === S.绝) tags.push({ 名: '化绝', 级: '凶', 断: '动爻化入本五行之绝（' + 本Wx + '绝在' + S.绝 + '）：主气尽势终。', 注: '觉子原注：土绝于巳须休囚方论绝，旺相则巳火反生土，论生不论绝。' });
      else if (变支 === S.长生) tags.push({ 名: '化长生', 级: '吉', 断: '动爻化出本五行长生（' + 本Wx + '长生在' + S.长生 + '）：主生机渐长。' });
      else if (变支 === S.帝旺) tags.push({ 名: '化帝旺', 级: '吉', 断: '动爻化出本五行帝旺（' + 本Wx + '旺在' + S.帝旺 + '）：主势力到顶。' });
    }

    // 4.3 进神 / 退神（同五行内进退）
    if (JIN[本支] === 变支) tags.push({ 名: '化进神', 级: '吉', 断: '动爻化进神（' + 本支 + '→' + 变支 + '）：势增，吉事倍增其势，凶事亦加其凶。' });
    if (TUI[本支] === 变支) tags.push({ 名: '化退神', 级: '凶', 断: '动爻化退神（' + 本支 + '→' + 变支 + '）：势减，吉凶皆渐减其威，虎头蛇尾。' });
    if (本支 === '戌' && 变支 === '丑') tags.push({ 名: '戌化丑（流派进神）', 级: '？', 断: '戌化丑：部分书作「土气一周复始」之进神，《卜筮正宗》原文未列，本内核单列提示，不并入主判。' });

    // 4.4 生克（力层，与象层并行给出）
    if (SHENG[变Wx] === 本Wx) tags.push({ 名: '回头生', 级: '吉', 断: '变爻五行生本爻：回头生，得后续支援，谋事易成。' });
    else if (KE[变Wx] === 本Wx) tags.push({ 名: '回头克', 级: '凶', 断: '变爻五行克本爻：回头克，半路折损，功败垂成。野鹤云「不论用神衰旺，皆以凶推」。' });
    else if (SHENG[本Wx] === 变Wx) tags.push({ 名: '化泄', 级: '平', 断: '本爻生变爻：我去生他，泄气，力减而不凶。' });
    else if (KE[本Wx] === 变Wx) tags.push({ 名: '化耗', 级: '平', 断: '本爻克变爻：我去克他，耗力，不为凶。' });
    else tags.push({ 名: '化比和', 级: '平', 断: '本爻与变爻同五行：比和，力持平。' });

    // 4.5 化空 / 化破
    if (空亡 && 空亡.length && 空亡.indexOf(变支) >= 0) tags.push({ 名: '化空', 级: '凶', 断: '变爻落旬空：有动作无结果，待出旬填实方应。' });
    if (月支 && 支冲(变支, 月支)) tags.push({ 名: '化破', 级: '凶', 断: '变爻被月建冲：化破，变化落空，出月方应。' });

    // 4.6 化刑
    if (支刑(本支, 变支)) tags.push({ 名: '化刑', 级: '凶', 断: '变爻与本爻相刑：主纠缠刑伤、事多枝节。' });

    // 主判：凶象优先（回头克 > 化墓化绝 > 反吟伏吟 > 退神），吉象次之
    var 序 = { '回头克': 1, '化墓': 2, '化绝': 2, '反吟': 3, '伏吟': 3, '化破': 4, '化空': 4, '化刑': 5, '化退神': 6, '化长生': 7, '回头生': 8, '化进神': 9, '化帝旺': 10 };
    var 主 = null;
    tags.forEach(function (t) { var n = 序[t.名] || 99; if (!主 || n < (序[主.名] || 99)) 主 = t; });
    return { 本支: 本支, 变支: 变支, 本五行: 本Wx, 变五行: 变Wx, 项: tags, 主判: 主 };
  }

  // ===== ⑤ 三合局 =====
  /**
   * @param 动 [{爻, 本支, 变支}]
   * 成局四法：三爻齐动 / 两爻动连变爻 / 两爻动＋日月凑 / 一爻动＋日月凑（中神动）
   */
  function 三合局(动, 月支, 日支, 空亡) {
    var pool = [];
    (动 || []).forEach(function (d) {
      if (d.本支) pool.push({ 支: d.本支, 源: '第' + d.爻 + '爻动', 动: true });
      if (d.变支) pool.push({ 支: d.变支, 源: '第' + d.爻 + '爻变', 动: true });
    });
    if (月支) pool.push({ 支: 月支, 源: '月建', 动: false });
    if (日支) pool.push({ 支: 日支, 源: '日辰', 动: false });

    var out = [];
    SAN_HE.forEach(function (g) {
      var hit = [];
      g.支.forEach(function (z) {
        var f = pool.filter(function (p) { return p.支 === z; })[0];
        if (f) hit.push(f);
      });
      var 动数 = hit.filter(function (h) { return h.动; }).length;
      if (hit.length === 3 && 动数 >= 1) {
        var 空 = hit.filter(function (h) { return 空亡 && 空亡.indexOf(h.支) >= 0; });
        out.push({
          局: g.局 + '局', 支: g.支.join(''), 中神: g.中神,
          来源: hit.map(function (h) { return h.支 + '（' + h.源 + '）'; }).join(' + '),
          成立: true,
          缺: '', 空破: 空.map(function (h) { return h.支; }),
          说明: '三合' + g.局 + '局成（' + g.支.join('') + '，中神' + g.中神 + '）。'
            + (空.length ? '局中' + 空.map(function (h) { return h.支; }).join('、') + '旬空，待填实之日成局。' : '')
        });
      } else if (hit.length === 2 && 动数 >= 2) {
        var 缺 = g.支.filter(function (z) { return !pool.some(function (p) { return p.支 === z; }); })[0];
        out.push({
          局: g.局 + '局', 支: g.支.join(''), 中神: g.中神,
          来源: hit.map(function (h) { return h.支 + '（' + h.源 + '）'; }).join(' + '),
          成立: false, 缺: 缺, 空破: [],
          说明: '两爻动而缺「' + 缺 + '」，不成局，为「虚一待用」；待' + 缺 + '日月补凑方成。'
        });
      }
    });
    return out;
  }

  // ===== ⑥ 卦象（六冲/六合/伏吟/反吟/游魂归魂）=====
  function 卦象(本卦, 变卦, 本支六, 变支六, 动爻, info, bianInfo) {
    var out = { 本卦: 本卦, 变卦: 变卦, 项: [] };
    if (CHONG_GUA.indexOf(本卦) >= 0) out.项.push({ 名: '本卦六冲', 断: '六冲卦：主冲突、冲散、快速、多变；吉事易散，凶事易消；近病逢冲即愈，久病逢冲则危。' });
    if (HE_GUA.indexOf(本卦) >= 0) out.项.push({ 名: '本卦六合', 断: '六合卦：主和合、团聚、长久、牵绊；吉事宜合，凶事忌合（忧疑之事反主缠绵难解）。' });
    if (变卦) {
      if (CHONG_GUA.indexOf(变卦) >= 0) out.项.push({ 名: '变卦六冲', 断: '变卦六冲：事终易散，谋事虽成亦有始无终。' });
      if (HE_GUA.indexOf(变卦) >= 0) out.项.push({ 名: '变卦六合', 断: '变卦六合：事终和合，先难后易、先散后聚。' });
    }
    if (info && info.代 === 6) out.项.push({ 名: '本卦游魂', 断: '游魂卦：心神不定、去而复返、事多变动。' });
    if (info && info.代 === 7) out.项.push({ 名: '本卦归魂', 断: '归魂卦：事归本位、有始有终，然亦主拘束难脱。' });
    if (bianInfo && bianInfo.代 === 6) out.项.push({ 名: '变卦游魂', 断: '变卦游魂：事终仍多变动，难以落定。' });
    if (bianInfo && bianInfo.代 === 7) out.项.push({ 名: '变卦归魂', 断: '变卦归魂：事终归本位，结局收敛。' });

    // 卦之反吟（本卦与变卦的上下卦互为相冲对）
    if (变卦 && bianInfo && info) {
      FAN_YIN_PAIR.forEach(function (p) {
        if ((info.下 === p[0] && bianInfo.下 === p[1]) || (info.下 === p[1] && bianInfo.下 === p[0])) {
          out.项.push({ 名: '内卦反吟', 断: '内卦反吟（' + info.下 + '↔' + bianInfo.下 + '）：内不安，我乱他定。' });
        }
        if ((info.上 === p[0] && bianInfo.上 === p[1]) || (info.上 === p[1] && bianInfo.上 === p[0])) {
          out.项.push({ 名: '外卦反吟', 断: '外卦反吟（' + info.上 + '↔' + bianInfo.上 + '）：外不安，他乱我定。' });
        }
      });
    }

    // 卦之伏吟 / 反吟（按支比较：只比该卦三爻是否全同 / 全冲）
    function seg(a, b, s) {
      var same = true, chong = true;
      for (var i = s; i < s + 3; i++) {
        if (!a[i] || !b[i]) return null;
        if (a[i] !== b[i]) same = false;
        if (!支冲(a[i], b[i])) chong = false;
      }
      return { same: same, chong: chong };
    }
    var 动内 = (动爻 || []).some(function (n) { return n <= 3; });
    var 动外 = (动爻 || []).some(function (n) { return n >= 4; });
    if (变支六 && 本支六) {
      var s内 = 动内 ? seg(本支六, 变支六, 0) : null;
      var s外 = 动外 ? seg(本支六, 变支六, 3) : null;
      if (s内 && s内.same) out.项.push({ 名: '内卦伏吟', 断: '内卦三爻地支未变：内卦伏吟，我心不快、内事呻吟。' });
      else if (s内 && s内.chong) out.项.push({ 名: '内卦反吟（爻级）', 断: '内卦三爻地支全冲：内卦反吟，内事反复不宁。' });
      if (s外 && s外.same) out.项.push({ 名: '外卦伏吟', 断: '外卦三爻地支未变：外卦伏吟，他心不安、外事迟滞。' });
      else if (s外 && s外.chong) out.项.push({ 名: '外卦反吟（爻级）', 断: '外卦三爻地支全冲：外卦反吟，外事反复多变。' });
    }
    return out;
  }

  // ===== ⑦ 主分析 =====
  /**
   * @param inp 与 liuyao.cast 同参：{ y,m,d,h?, backs?:[6], 事?:'财运' }
   * @returns 完整旺衰报告
   */
  function analyze(inp) {
    if (!LYAO || !LYAO.cast) return { err: '六爻旺衰需 liuyao 内核' };
    var c = LYAO.cast(inp || {});
    if (c.err) return c;

    var 月支 = c.月建 || null, 日支 = c.日辰 || null, 空亡 = c.旬空 || [];
    var 用神Key = (inp && inp.事 && LYAO.YONG[inp.事]) ? LYAO.YONG[inp.事] : null;

    // 变卦纳甲按爻位对齐
    var 变支六 = (c.变卦纳甲 || []).map(function (g) { return g ? g.charAt(1) : null; });
    var 本支六 = (c.本卦纳甲 || []).map(function (g) { return g.charAt(1); });

    // 逐爻旺衰
    var rows = c.爻线.map(function (l, i) {
      var 支 = l.干支.charAt(1);
      var m = 月关系(支, l.五行, 月支);
      var d = 日关系(支, l.五行, 日支);
      var 档 = 旺衰档(m.类, d.类);
      var 动 = l.动静 !== '静';

      // 日冲 → 暗动 / 日破 / 冲散
      var 冲判 = null;
      if (d.类 === '日冲') {
        var 月旺 = (m.类 === '临月建' || m.类 === '月生' || m.类 === '月扶');
        if (动) { 冲判 = '冲散'; 档 = '动爻被日辰冲（冲散，力散）'; }
        else if (m.类 === '月破') { 冲判 = '暗动'; 档 = '月破反作暗动（值日不破）'; }
        else if (月旺) { 冲判 = '暗动'; 档 = '暗动（旺相受冲，力增，同动爻）'; }
        else { 冲判 = '日破'; 档 = '日破（休囚受冲，失力）'; }
      }

      // 月建冲临日辰之静爻 → 一派作暗动，如实标注
      var 月冲注 = '';
      if (m.类 === '月破' && d.类 === '临日辰' && !动) {
        月冲注 = '流派分歧：月建冲「临日辰」之静爻，一派作暗动，一派认为月冲无暗动（本内核择暗动）。';
      }

      var 变 = null;
      if (动 && 变支六[i]) 变 = 变爻关系(支, 变支六[i], 月支, 日支, 空亡);

      return {
        爻: i + 1, 干支: l.干支, 支: 支, 五行: l.五行, 六亲: l.六亲, 六神: l.六神,
        世应: l.世应, 动静: l.动静, 动: 动,
        月: m, 日: d, 旺衰: 档, 强弱: 档强弱(档),
        冲判: 冲判, 月冲注: 月冲注,
        空亡: 空亡.indexOf(支) >= 0,
        月破: m.类 === '月破',
        变: 变
      };
    });

    // 用神定位（本卦现 / 伏神）
    var 用神爻们 = 用神Key ? rows.filter(function (r) { return r.六亲 === 用神Key; }) : [];
    var 伏神 = null;
    if (用神Key && !用神爻们.length) {
      var hid = (c.伏飞神 || []).filter(function (f) { return f.伏神.六亲 === 用神Key; });
      if (hid.length) 伏神 = hid.map(function (f) {
        var 支 = f.伏神.干支.charAt(1);
        var m = 月关系(支, f.伏神.五行, 月支);
        var d = 日关系(支, f.伏神.五行, 日支);
        return {
          爻: f.爻, 干支: f.伏神.干支, 五行: f.伏神.五行, 六亲: f.伏神.六亲,
          飞神: f.飞神, 飞伏关系: f.飞伏关系,
          月: m, 日: d, 旺衰: 旺衰档(m.类, d.类),
          强弱: 档强弱(旺衰档(m.类, d.类)), 空亡: 空亡.indexOf(支) >= 0
        };
      });
    }

    // 原神 / 忌神 / 仇神（以用神五行为轴）
    var 用Wx = 用神爻们.length ? 用神爻们[0].五行 : (伏神 && 伏神.length ? 伏神[0].五行 : null);
    var 元忌仇 = null;
    if (用Wx) {
      var 原Wx = 生我(用Wx), 忌Wx = 克我(用Wx), 仇Wx = 原Wx ? 克我(原Wx) : null;
      function 找(六亲名) { return rows.filter(function (r) { return r.六亲 === 六亲名; }); }
      var QIN_OF_WX = {};
      rows.forEach(function (r) { QIN_OF_WX[r.五行] = r.六亲; });
      var 名 = function (wx) { return wx ? (QIN_OF_WX[wx] || wx) : '—'; };
      元忌仇 = {
        用神五行: 用Wx,
        原神: { 五行: 原Wx, 六亲: 名(原Wx), 爻: 原Wx ? 找(名(原Wx)).map(function (r) { return { 爻: r.爻, 旺衰: r.旺衰, 强弱: r.强弱, 空亡: r.空亡, 月破: r.月破 }; }) : [] },
        忌神: { 五行: 忌Wx, 六亲: 名(忌Wx), 爻: 忌Wx ? 找(名(忌Wx)).map(function (r) { return { 爻: r.爻, 旺衰: r.旺衰, 强弱: r.强弱, 空亡: r.空亡, 月破: r.月破 }; }) : [] },
        仇神: { 五行: 仇Wx, 六亲: 名(仇Wx), 爻: 仇Wx ? 找(名(仇Wx)).map(function (r) { return { 爻: r.爻, 旺衰: r.旺衰, 强弱: r.强弱, 空亡: r.空亡, 月破: r.月破 }; }) : [] }
      };
    }

    // 三合局
    var 动Info = rows.filter(function (r) { return r.动; }).map(function (r) {
      return { 爻: r.爻, 本支: r.支, 变支: r.变 ? r.变.变支 : null };
    });
    var 合局 = 三合局(动Info, 月支, 日支, 空亡);

    // 卦象
    var 本Info = LYAO.GUA_INDEX[c.本卦];
    var 变Info = c.变卦 ? LYAO.GUA_INDEX[c.变卦] : null;
    var 象 = 卦象(c.本卦, c.变卦, 本支六, 变支六, c.动爻 || [], 本Info, 变Info);

    // 世爻
    var 世 = rows[c.世 - 1] || null;

    return {
      本卦: c.本卦, 变卦: c.变卦, 动爻: c.动爻,
      宫: c.宫, 世: c.世, 应: c.应,
      月建: 月支, 日辰: 日支, 日干: c.日干, 旬空: 空亡,
      用神: 用神Key, 用神五行: 用Wx,
      用神爻: 用神爻们, 用神伏神: 伏神,
      世爻: 世,
      元忌仇: 元忌仇,
      爻: rows,
      合局: 合局,
      卦象: 象,
      缺料: c.缺料 || '',
      注: [
        '旺衰档为《增删卜易》日月权衡表的直接落地，只出定性（旺/相/平/衰），不打分。',
        '生旺墓绝取《卜筮正宗》原文：金巳酉丑寅、木亥卯未申、火寅午戌亥、水土申子辰巳。',
        '流派分歧已标注不合并：①土长生申（《易冒》另有寅说）②月建冲临日之静爻是否作暗动 ③戌化丑是否进神。',
        '墓绝两象须兼看旺衰：觉子原注「旺相得生扶则论生不论墓/绝」。'
      ]
    };
  }

  return {
    analyze: analyze,
    月关系: 月关系, 日关系: 日关系, 旺衰档: 旺衰档, 档强弱: 档强弱,
    变爻关系: 变爻关系, 三合局: 三合局, 卦象: 卦象,
    SHENG12: SHENG12, JIN: JIN, TUI: TUI, HE: HE, SAN_HE: SAN_HE,
    CHONG_GUA: CHONG_GUA, HE_GUA: HE_GUA, FAN_YIN_PAIR: FAN_YIN_PAIR,
    Z_WX: Z_WX, SHENG: SHENG, KE: KE, 支冲: 支冲, 支合: 支合, 支刑: 支刑
  };
});
